  "Every card is a PowerPoint shape with its own text: retype, move or recolour it. The lines are separate shapes, so after moving a card, move its line too. The slides follow what is on screen: the board picked, the filters and Show to.": "การ์ดทุกใบเป็นรูปร่าง PowerPoint ที่มีข้อความของตัวเอง: พิมพ์ใหม่ ย้าย หรือเปลี่ยนสีได้ เส้นเป็นรูปร่างแยกกัน ดังนั้นเมื่อย้ายการ์ดให้ย้ายเส้นของการ์ดด้วย สไลด์จะตามสิ่งที่แสดงบนหน้าจอ ได้แก่ บอร์ดที่เลือก ตัวกรอง และ แสดงถึง",
  "Every clash has a side": "ทุกความขัดแย้งต้องเลือกฝ่าย",
  "Every decision and reason is saved in the merge log, linked from the “Forecast merged” note on this day. The forecast itself is kept, read-only.": "ทุกการตัดสินใจและเหตุผลจะถูกบันทึกไว้ในบันทึกการรวม โดยมีลิงก์จากหมายเหตุ “Forecast merged” ของวันนี้ ส่วนคาดการณ์จะยังเก็บไว้แบบอ่านอย่างเดียว",
  "Every difference needs a decision before it can be applied.": "ทุกความแตกต่างต้องมีการตัดสินใจก่อนจึงจะใช้ได้",
  "Every host this employee has been deployed to, most recent first.": "โฮสต์ทั้งหมดที่พนักงานคนนี้เคยปฏิบัติงาน เรียงจากล่าสุด",
  "Every inspector ever deployed to this host, with how many days each has worked there. Sorts by how many inspectors know the site.": "ผู้ตรวจสอบทุกคนที่เคยปฏิบัติงานที่โฮสต์นี้ พร้อมจำนวนวันที่แต่ละคนทำงานที่นั่น เรียงตามจำนวนผู้ตรวจสอบที่รู้จักหน้างาน",
  "Every mission from that date is hidden. Unhide from \"Hide/Unhide\" first if you want to bring one forward.": "มิชชั่นทั้งหมดตั้งแต่วันที่นั้นถูกซ่อนอยู่ หากต้องการนำมิชชั่นใดมา ให้แสดงจาก \"ซ่อน/แสดง\" ก่อน",
  "Every mission on the latest confirmed day is hidden, so there is nothing to pick.": "มิชชั่นทั้งหมดในวันที่ยืนยันล่าสุดถูกซ่อนอยู่ จึงไม่มีอะไรให้เลือก",
  "Every one of those cells already has a number above 0 — nothing was changed.": "เซลล์เหล่านั้นทุกเซลล์มีตัวเลขมากกว่า 0 อยู่แล้ว — ไม่มีการเปลี่ยนแปลง",
  "Everyone who can be added is already on the list. Anyone else needs an account with the Engineer role or above first, under Users.": "ทุกคนที่เพิ่มได้อยู่ในรายการแล้ว คนอื่นต้องมีบัญชีที่มีบทบาทวิศวกรขึ้นไปก่อน ที่ผู้ใช้",
