  "Missions each engineer ran and the people they had out, per working day, busiest first. Same range and board as History.": "มิชชั่นที่วิศวกรแต่ละคนดูแลและจำนวนบุคลากรที่ส่งออกไป ต่อวันทำงาน เรียงจากมากที่สุด ช่วงเวลาและบอร์ดเดียวกับประวัติ",
  "Missions that already name them keep their record of who ran them, but lose the engineer on the card.": "มิชชั่นที่ระบุชื่อบุคคลนี้ไว้แล้วจะเก็บบันทึกว่าใครเป็นผู้ดูแล แต่จะไม่แสดงวิศวกรบนการ์ด",
  "Missions were added one by one, but the day has not been carried over from the last working day or merged from the forecast yet, so the whole team has not reviewed it.": "มิชชั่นถูกเพิ่มทีละรายการ แต่วันนี้ยังไม่ได้ยกแผนมาจากวันทำงานล่าสุดหรือรวมจากการคาดการณ์ ทีมจึงยังไม่ได้ตรวจสอบทั้งหมด",
  "Missions were added one by one, but the day has not been carried over from the last working day or merged from the forecast yet, so the whole team has not reviewed it. Today or a past date: view-only (editing asks first). Confirmed plans run up to Fri 16 Oct (the next working day); every later date opens as a forecast.": "มิชชั่นถูกเพิ่มทีละรายการ แต่วันนี้ยังไม่ได้ยกแผนมาจากวันทำงานล่าสุดหรือรวมจากการคาดการณ์ ทีมจึงยังไม่ได้ตรวจสอบทั้งหมด วันนี้หรือวันที่ผ่านมา: ดูได้อย่างเดียว (การแก้ไขจะถามก่อน) แผนที่ยืนยันแล้วมีถึงศ. 16 ต.ค. (วันทำงานถัดไป) วันที่หลังจากนั้นจะเปิดเป็นการคาดการณ์",
