  "Nothing is planned for this day yet. Use Carry over to start from the last working day, or Review & merge if there is a forecast.": "ยังไม่มีการวางแผนสำหรับวันนี้ ใช้ ยกแผนมา เพื่อเริ่มจากวันทำงานล่าสุด หรือ ตรวจสอบและรวม หากมีการคาดการณ์",
  "Nothing is planned for this day yet. Use Carry over to start from the last working day, or Review & merge if there is a forecast. Confirmed plans run up to Fri 16 Oct (the next working day); every later date opens as a forecast.": "ยังไม่มีการวางแผนสำหรับวันนี้ ใช้ ยกแผนมา เพื่อเริ่มจากวันทำงานล่าสุด หรือ ตรวจสอบและรวม หากมีการคาดการณ์ แผนที่ยืนยันแล้วมีถึงศ. 16 ต.ค. (วันทำงานถัดไป) วันที่หลังจากนั้นจะเปิดเป็นการคาดการณ์",
  "Nothing is planned for this day yet. Use Carry over to start from the last working day, or Review & merge if there is a forecast. Today or a past date: view-only (editing asks first). Confirmed plans run up to Fri 16 Oct (the next working day); every later date opens as a forecast.": "ยังไม่มีการวางแผนสำหรับวันนี้ ใช้ ยกแผนมา เพื่อเริ่มจากวันทำงานล่าสุด หรือ ตรวจสอบและรวม หากมีการคาดการณ์ วันนี้หรือวันที่ผ่านมา: ดูได้อย่างเดียว (การแก้ไขจะถามก่อน) แผนที่ยืนยันแล้วมีถึงศ. 16 ต.ค. (วันทำงานถัดไป) วันที่หลังจากนั้นจะเปิดเป็นการคาดการณ์",
  "Nothing is saved yet — you review every change first.": "ยังไม่มีการบันทึก — คุณจะได้ตรวจสอบทุกการเปลี่ยนแปลงก่อน",
  "Nothing on the chart to export: no boards are shown.": "ไม่มีข้อมูลในแผนภูมิให้ส่งออก: ไม่ได้แสดงบอร์ดใด",
