  "One image with the boards one under another. Send it as a file, not a photo, so it stays sharp. The file type and host columns are remembered on this device.": "รูปภาพเดียวที่เรียงบอร์ดต่อกันในแนวตั้ง ส่งเป็นไฟล์ ไม่ใช่รูปถ่าย เพื่อให้ภาพคมชัด ประเภทไฟล์และคอลัมน์โฮสต์จะถูกจดจำไว้ในอุปกรณ์นี้",
  "One sheet with every column of the list: location, Google Maps link, service area, note, inspectors, deployment days, boards, missions and first / last seen.": "หนึ่งชีตที่มีทุกคอลัมน์ของรายการ: สถานที่ ลิงก์ Google Maps พื้นที่บริการ หมายเหตุ ผู้ตรวจสอบ วันปฏิบัติงาน บอร์ด มิชชั่น และพบครั้งแรก / ล่าสุด",
  "One sheet with the same columns as the table (plus Years of Service, counted up to today), in the order shown. Only the table header — no banner. The language choice is remembered on this device.": "หนึ่งชีตที่มีคอลัมน์เดียวกับตาราง (เพิ่มอายุงาน นับถึงวันนี้) เรียงตามที่แสดง มีเฉพาะส่วนหัวตาราง ไม่มีแบนเนอร์ ภาษาที่เลือกจะถูกจดจำไว้ในอุปกรณ์นี้",
  "Only the missions brought in for today are on the board.": "บนบอร์ดมีเฉพาะมิชชั่นที่นำมาใส่สำหรับวันนี้",
