  "Sheet 1 has one row per person on a mission, in mission order. Every sheet carries the TRIGO header, board name, date and total. The columns above also apply to the extra sheets (Name is always kept). The file language (English / Thai) changes the headers and wording in the file; names, hosts and customers stay as typed. Your choices are remembered on this device.": "ชีต 1 มีหนึ่งแถวต่อบุคลากรหนึ่งคนในมิชชั่น เรียงตามลำดับมิชชั่น ทุกชีตมีส่วนหัว TRIGO ชื่อบอร์ด วันที่ และยอดรวม คอลัมน์ด้านบนใช้กับชีตเพิ่มเติมด้วย (ชื่อจะถูกเก็บไว้เสมอ) ภาษาของไฟล์ (อังกฤษ / ไทย) เปลี่ยนหัวคอลัมน์และข้อความในไฟล์ ส่วนชื่อ โฮสต์ และลูกค้าจะเป็นตามที่พิมพ์ไว้ ตัวเลือกของคุณจะถูกจำไว้ในอุปกรณ์นี้",
