  "Thu 22/10: 8 spare": "Thu 22/10: เหลือ 8",
  "Tick all": "ติ๊กทั้งหมด",
  "Tick at least one board to export.": "ติ๊กอย่างน้อยหนึ่งบอร์ดเพื่อส่งออก",
  "Ticked days are that board's non-working days (its weekend). This drives the holiday toggle, the weekend \"Copy from weekday\" import, the date picker's highlighting and both Overview trend charts.": "วันที่ติ๊กคือวันที่ไม่ใช่วันทำงานของบอร์ดนั้น (วันหยุดสุดสัปดาห์) ใช้กับตัวสลับวันหยุด การนำเข้า \"คัดลอกจากวันทำงาน\" ของวันหยุดสุดสัปดาห์ การเน้นสีของตัวเลือกวันที่ และแผนภูมิแนวโน้มทั้งสองในภาพรวม",
  "Ticked days are the board's weekend — they start empty and use \"Copy from weekday\". You can still override a single date later with \"Mark as Holiday\" / \"Unmark Holiday\".": "วันที่ติ๊กคือวันหยุดสุดสัปดาห์ของบอร์ด — เริ่มต้นว่างเปล่าและใช้ \"คัดลอกจากวันทำงาน\" คุณยังเปลี่ยนวันที่เดียวได้ภายหลังด้วย \"Mark as Holiday\" / \"Unmark Holiday\"",
  "Time": "เวลา",
  "Tip: \\\"Review changes\\\" in the banner above updates only what changed, and keeps everything else on this day.": "เคล็ดลับ: \\\"Review changes\\\" ในแบนเนอร์ด้านบนจะอัปเดตเฉพาะสิ่งที่เปลี่ยน และคงส่วนอื่นของวันนี้ไว้",
  "To rename or merge a host use its Edit dialog / Review duplicates, which also fixes its missions.": "หากต้องการเปลี่ยนชื่อหรือรวมโฮสต์ ให้ใช้กล่องแก้ไขหรือตรวจสอบรายการซ้ำ ซึ่งจะแก้มิชชั่นของโฮสต์ด้วย",
  "To take someone's access away while keeping their record — and the \"locked by\" and \"updated by\" history that names them — set their status to Disabled instead.": "หากต้องการเพิกถอนสิทธิ์เข้าถึงของใครแต่คงระเบียนไว้ รวมถึงประวัติ \"ล็อกโดย\" และ \"อัปเดตโดย\" ที่ระบุชื่อเขา ให้ตั้งสถานะเป็นปิดใช้งานแทน",
  "Today's hosts that only one or two people have ever worked, and where those people are today.": "โฮสต์ของวันนี้ที่มีคนเคยทำงานเพียงหนึ่งหรือสองคน และตำแหน่งของคนเหล่านั้นในวันนี้",
  "Today's plan (15-Oct-2026) is already being executed and is read-only. Do you want to edit it anyway?": "แผนของวันนี้ (15-Oct-2026) กำลังดำเนินการและเป็นแบบอ่านอย่างเดียว ต้องการแก้ไขอยู่หรือไม่?",
