  "Use Board One's deployment on Thu 15 Oct as the starting demand: Host Alpha: 2, Host Beta: 1, Host Gamma (night): 1. It goes into 30 empty cells across the next 2 weeks. Cells that already have a number above 0 are kept (a 0 counts as empty). Then adjust the hosts you look after.": "ใช้การปฏิบัติงานของ Board One ในวันที่ Thu 15 Oct เป็นความต้องการเริ่มต้น: Host Alpha: 2, Host Beta: 1, Host Gamma (night): 1 จะใส่ลงใน 30 เซลล์ว่างในช่วง 2 สัปดาห์ถัดไป เซลล์ที่มีตัวเลขมากกว่า 0 อยู่แล้วจะคงไว้ (0 นับเป็นว่าง) จากนั้นปรับโฮสต์ที่คุณดูแล",
