  "You own your display name and phone number. An administrator controls your role and account status.": "ชื่อที่แสดงและเบอร์โทรศัพท์เป็นของคุณ ผู้ดูแลระบบควบคุมบทบาทและสถานะบัญชีของคุณ",
  "You'll see the new one on the next screen — it is shown once, so pass it on before you close it.": "คุณจะเห็นรหัสใหม่ในหน้าจอถัดไป ซึ่งแสดงเพียงครั้งเดียว ให้ส่งต่อให้เขาก่อนปิด",
  "Your access to this app has been switched off. Ask an admin if you think that's a mistake.": "สิทธิ์เข้าใช้แอปนี้ของคุณถูกปิดแล้ว หากคิดว่าผิดพลาด ให้ถามผู้ดูแลระบบ",
