  "Your role can view the roster but not change it.": "บทบาทของคุณดูรายชื่อพนักงานได้แต่เปลี่ยนแปลงไม่ได้",
  "Your role can view this board but not change it.": "บทบาทของคุณดูบอร์ดนี้ได้แต่เปลี่ยนแปลงไม่ได้",
  "Your role can view this list but not change it.": "บทบาทของคุณดูรายการนี้ได้แต่เปลี่ยนแปลงไม่ได้",
  "Your role decides which tabs you see and what you can change. Only an admin can alter it.": "บทบาทของคุณกำหนดว่าคุณเห็นแท็บใดและเปลี่ยนแปลงอะไรได้ เฉพาะผู้ดูแลระบบเท่านั้นที่แก้ไขได้",
  "Your role doesn't have access to any part of the app yet. Ask an admin to give it something in Settings → Roles.": "บทบาทของคุณยังไม่มีสิทธิ์เข้าถึงส่วนใดของแอป ขอให้ผู้ดูแลระบบกำหนดให้ที่ ตั้งค่า → บทบาท",
  "Your role doesn\\'t have access to any of the Overview sections. Ask an admin if you think that\\'s wrong.": "บทบาทของคุณไม่มีสิทธิ์เข้าถึงส่วนใดของภาพรวม หากคิดว่าผิดพลาด ให้ถามผู้ดูแลระบบ",
