  "removes access. Hiding an Overview section keeps it off the page and skips its query; it is not a data barrier — those sections are worked out from the same mission and assignment records the board itself needs, so treat it as tidying the dashboard, not as protecting a secret.": "จะนำสิทธิ์เข้าถึงออก การซ่อนส่วนของภาพรวมจะไม่แสดงบนหน้าและข้ามการสืบค้นของส่วนนั้น แต่ไม่ใช่การป้องกันข้อมูล — ส่วนเหล่านี้คำนวณจากข้อมูลมิชชั่นและการมอบหมายชุดเดียวกับที่บอร์ดใช้ ให้ถือว่าเป็นการจัดหน้าแดชบอร์ดให้เรียบร้อย ไม่ใช่การปกป้องความลับ",
