  "— none —": "— ไม่มี —",
  "• Changing a Board clears that person's assignment on the day you are viewing in the app.": "• การเปลี่ยนบอร์ดจะล้างการมอบหมายของคนนั้นในวันที่คุณกำลังดูอยู่ในแอป",
  "• Do not edit or delete the grey ID column. It is how the app tracks a row, so you can rename someone safely.": "• อย่าแก้ไขหรือลบคอลัมน์ ID สีเทา แอปใช้คอลัมน์นี้ติดตามแต่ละแถว คุณจึงเปลี่ยนชื่อคนได้อย่างปลอดภัย",
  "• Google Maps link must start with https://.": "• ลิงก์ Google Maps ต้องขึ้นต้นด้วย https://",
  "• Only the columns present are updated. Delete a column you do not want touched. Keep the header names.": "• อัปเดตเฉพาะคอลัมน์ที่มีอยู่ ลบคอลัมน์ที่ไม่ต้องการให้แก้ไข และคงชื่อหัวคอลัมน์ไว้",
  "• Rows you delete from the file are NOT deleted in the app. To retire someone, set Status to Inactive.": "• แถวที่คุณลบออกจากไฟล์จะไม่ถูกลบในแอป หากต้องการให้ใครออกจากระบบ ให้ตั้งสถานะเป็นไม่ใช้งาน",
  "• Status: Active or Archived. Hosts are never deleted by an upload.": "• สถานะ: ใช้งานอยู่ หรือ เก็บถาวร การอัปโหลดจะไม่ลบโฮสต์",
