  "No missions on this board in the last few working days. Start the day with a new mission instead.": "ไม่มีมิชชั่นบนบอร์ดนี้ในช่วงวันทำงานที่ผ่านมา เริ่มวันนี้ด้วยมิชชั่นใหม่แทน",
