  "A hidden mission \"{a}\" already exists on the {b} shift for this date. Use \"Hide/Unhide\" to unhide and reuse it, or pick a different shift.": "มีมิชชั่นที่ซ่อนอยู่ชื่อ \"{a}\" ในกะ{b}ของวันนี้แล้ว ใช้ \"ซ่อน/แสดง\" เพื่อแสดงและนำกลับมาใช้ หรือเลือกกะอื่น",
  "A mission \"{a}\" already exists on the {b} shift for this date. Use a different shift, or edit the existing mission instead.": "มีมิชชั่นชื่อ \"{a}\" ในกะ{b}ของวันนี้แล้ว ใช้กะอื่น หรือแก้ไขมิชชั่นที่มีอยู่แทน",
