  "Missions on the confirmed board for {a} {b} · tick the ones you will work on for {c} {d}": "มิชชั่นบนบอร์ดที่ยืนยันแล้วของ {a} {b} · ติ๊กมิชชั่นที่คุณจะทำในวัน {c} {d}",
