  "Move {b} anyway? The engineer who placed {c} will see a red flag on their mission until they acknowledge it.": "ย้าย {b} ต่อไปหรือไม่ วิศวกรที่จัด {c} ไว้จะเห็นธงสีแดงบนมิชชั่นของตนจนกว่าจะรับทราบ",
