  "{a} employees selected": "เลือกพนักงานแล้ว {a} คน",
  "{a} eng · {b} areas · {c} miss · {d} crew": "{a} วิศวกร · {b} พื้นที่ · {c} มิชชั่น · {d} ทีมงาน",
  "{a} filled-in {b} being cleared": "{a} ช่องที่กรอกแล้ว {b} กำลังถูกล้าง",
  "{a} for {b}": "{a} สำหรับ {b}",
  "{a} for {b} on {c} {d}": "{a} สำหรับ {b} วันที่ {c} {d}",
  "{a} forecast alerts": "การแจ้งเตือนคาดการณ์ {a} รายการ",
  "{a} forecast alert{b} sent": "ส่งการแจ้งเตือนคาดการณ์ {a} รายการแล้ว",
  "{a} free. That is surge capacity, so no action is needed.": "ว่าง {a} เป็นกำลังสำรองรองรับงานเร่งด่วน จึงไม่ต้องดำเนินการ",
  "{a} has no confirmed working day with missions to start from.": "{a} ไม่มีวันทำงานที่ยืนยันแล้วและมีมิชชั่นให้เริ่มต้น",
  "{a} has no numbers in the weeks shown — it is already a clean sheet.": "{a} ไม่มีตัวเลขในสัปดาห์ที่แสดง — เป็นแผ่นว่างอยู่แล้ว",
  "{a} hidden. It is in Hide/Unhide if you need it back.": "ซ่อน {a} แล้ว อยู่ในซ่อน/แสดง หากต้องการนำกลับมา",
  "{a} hold{b} taken from you": "{a} รายการจองถูกนำไปจากคุณ",
  "{a} host names fall into {b} look-alike groups — merge each group into its real host so their missions and inspector day counts join up.": "ชื่อโฮสต์ {a} ชื่อจัดเป็นกลุ่มที่คล้ายกัน {b} กลุ่ม — รวมแต่ละกลุ่มเข้ากับโฮสต์จริง เพื่อให้มิชชั่นและจำนวนวันของผู้ตรวจสอบรวมกัน",
  "{a} host names look like the same site — merge them into the real one so their missions and inspector day counts join up.": "ชื่อโฮสต์ {a} ชื่อดูเหมือนไซต์เดียวกัน — รวมเข้ากับโฮสต์จริง เพื่อให้มิชชั่นและจำนวนวันของผู้ตรวจสอบรวมกัน",
  "{a} hosts: {b} with a location, {c} without, {d} archived": "โฮสต์ {a} รายการ: มีสถานที่ {b} ไม่มี {c} เก็บถาวร {d}",
  "{a} host{b} using it will have no area set.": "โฮสต์ {a} รายการที่ใช้อยู่จะไม่มีพื้นที่กำหนด",
  "{a} inspector{b}": "ผู้ตรวจสอบ {a} คน",
  "{a} inspector{b} ever deployed here": "{a} ผู้ตรวจสอบเคยปฏิบัติงานที่นี่",
  "{a} is active again — back on today's and future boards.": "{a} ใช้งานอยู่อีกครั้ง — กลับมาในบอร์ดวันนี้และอนาคต",
  "{a} is active again — offered when creating a mission.": "{a} ใช้งานอยู่อีกครั้ง — แสดงเป็นตัวเลือกเมื่อสร้างมิชชั่น",
  "{a} is already in the host list — edit that row instead.": "{a} อยู่ในรายการโฮสต์แล้ว — แก้ไขแถวนั้นแทน",
  "{a} is in the past and read-only. Do you want to edit its saved plan?": "{a} เป็นวันที่ผ่านมาแล้วและอ่านอย่างเดียว ต้องการแก้ไขแผนที่บันทึกไว้หรือไม่",
  "{a} is longer than {b} characters": "{a} ยาวเกิน {b} ตัวอักษร",
  "{a} is the only board. Create another board before deleting this one.": "{a} เป็นบอร์ดเดียว สร้างบอร์ดอื่นก่อนลบบอร์ดนี้",
  "{a} kept": "คง {a} ไว้",
  "{a} kept on {b}": "{a} คงไว้ที่ {b}",
  "{a} kept {b} on {c} at {d} instead of {e} {f}{g}": "{a} คง {b} ไว้ในวันที่ {c} ที่ {d} แทน {e} {f}{g}",
  "{a} kept {b} on {c} instead of {d} {e}{f}": "{a} คง {b} ไว้ในวันที่ {c} แทน {d} {e}{f}",
  "{a} merged your forecast for {b}: {c} parts of it were not used.": "{a} รวมคาดการณ์ของคุณสำหรับ {b} แล้ว: ไม่ได้ใช้ {c} ส่วน",
  "{a} merged {b} forecast for {c}.": "{a} รวมคาดการณ์ {b} สำหรับ {c} แล้ว",
  "{a} miss · {b} crew": "{a} มิชชั่น · {b} ทีมงาน",
