  "Days on a mission and days on leave in the period, on planned working days (a day with no missions on the person's board is left out, as in Overview History), and under them the leave share: amber above 20%, red above 30%. Exchange Working Day is not leave: it is worked back. Shown to roles that can see Overview History.": "จำนวนวันที่ปฏิบัติมิชชั่นและวันที่ลาในช่วงนั้น นับเฉพาะวันทำงานตามแผน (วันที่บอร์ดของบุคคลนั้นไม่มีมิชชั่นจะไม่นับ เช่นเดียวกับประวัติในภาพรวม) และด้านล่างคือสัดส่วนการลา: สีเหลืองอำพันเมื่อเกิน 20% สีแดงเมื่อเกิน 30% วันแลกวันทำงานไม่ใช่การลา เพราะต้องทำงานชดเชย แสดงเฉพาะบทบาทที่ดูประวัติในภาพรวม ได้",
  "Days on a mission in the period, on planned working days. Shown to roles that can see Overview History.": "จำนวนวันที่ปฏิบัติมิชชั่นในช่วงนั้น นับเฉพาะวันทำงานตามแผน แสดงเฉพาะบทบาทที่ดูประวัติในภาพรวม ได้",
  "Whether the host is Active or Archived, and under it what needs a look: no location or Maps link, or too few experienced people left (at risk). Archived hosts keep their row and all of their history here, but are no longer offered when creating a mission. Use it for a site you no longer serve — a duplicate or a typo should be merged instead.": "โฮสต์ใช้งานอยู่หรือเก็บถาวร และด้านล่างคือสิ่งที่ต้องตรวจสอบ: ไม่มีสถานที่หรือลิงก์ Maps หรือเหลือผู้ชำนาญน้อยเกินไป (เสี่ยง) โฮสต์ที่เก็บถาวรยังอยู่ในรายการพร้อมประวัติทั้งหมด แต่จะไม่แสดงเมื่อสร้างมิชชั่น ใช้กับไซต์ที่ไม่ให้บริการแล้ว ส่วนชื่อซ้ำหรือพิมพ์ผิดให้รวมเข้าด้วยกันแทน",
