  "How many people are experienced at this site (Settings → Host experience), and under it how many people have ever worked there and how many days in all. Sorts by how many are experienced.": "จำนวนผู้ที่ชำนาญหน้างานนี้ (การตั้งค่า → ความชำนาญหน้างาน) และด้านล่างคือจำนวนคนที่เคยทำงานที่นั่นและจำนวนวันรวม เรียงตามจำนวนผู้ชำนาญ",
  "The last day anyone worked at this host.": "วันล่าสุดที่มีผู้ปฏิบัติงานที่โฮสต์นี้",
  "How many people have ever been deployed to this host. Sorts by how many people know the site.": "จำนวนคนที่เคยถูกส่งไปโฮสต์นี้ เรียงตามจำนวนผู้ที่ชำนาญหน้างาน",
  "The mission number (a gold star beside it: the mission is highlighted on the board that day), and under it the customer.": "หมายเลขมิชชั่น (ดาวสีทองข้างหมายเลข: มิชชั่นถูกไฮไลต์บนบอร์ดในวันนั้น) และด้านล่างคือลูกค้า",
